 if(added&&progress>0&&r.remaining[0].mass>1e-8)s+='<path d="M201 340Q246 '+(338-Math.min(20,r.remaining[0].mass*2))+' 280 336Q320 '+(338-Math.min(14,r.remaining[0].mass))+' 359 340V351H201Z" fill="#fffdf0" data-solid="remaining-soda"/>';
 if(added)s+='<path d="M279 104V185" stroke="#91aaa4" stroke-width="2"/><g transform="rotate('+(-65*Math.min(1,progress*6))+' 279 186)" data-solid="prepared-cup"><path d="M263 186H297V214Q280 220 263 214Z" fill="#edf2e7" stroke="#a6b5aa"/>'+(progress<.18?'<path d="M267 207Q280 200 293 207V214H267Z" fill="#fffdf1" opacity="'+(1-progress/.18)+'"/>':'')+'</g>';
 if(progress>0&&progress<1)s+=Array.from({length:Math.min(28,Math.ceil(r.co2*4)+3)},(_,i)=>'<circle class="gas-bubble" style="--delay:-'+i*.21+'s;--travel:115px" cx="'+(225+i*23%106)+'" cy="'+(325-((progress*280+i*23)%110))+'" r="'+(2+i%3)+'" fill="#fff" stroke="#8db9b6" opacity=".8"/>').join('');
 s+='</g><path d="M258 102H300V180L364 322Q376 347 352 350H206Q182 347 194 322L258 180Z" fill="url(#clear-glass)" stroke="#749b9e" stroke-width="2.5"/><path d="M267 112V181L205 327" fill="none" stroke="#fff" stroke-width="5" opacity=".8"/><ellipse cx="279" cy="102" rx="22" ry="5" fill="#edf5f2" stroke="#749b9e"/>'+[265,290,315].map((y,i)=>'<path d="M'+(327+i*9)+' '+y+'h-20" stroke="#7a9ca0"/>').join('');
 s+='<path d="M589 124V347M555 348H620" stroke="#9bb0a4" stroke-width="6" stroke-linecap="round"/>';
 const inflate=closed&&collect?r.contained:0,rx=28+Math.min(26,inflate*5),ry=18+Math.min(74,inflate*14);
 s+='<g><path d="M560 132V'+(224-ry)+'" stroke="#a5bbb4" stroke-width="8"/><ellipse cx="560" cy="224" rx="'+rx+'" ry="'+ry+'" fill="#d3dfc2" fill-opacity=".66" stroke="#95ae8b" stroke-width="2"/><path d="M'+(560-rx*.6)+' '+(224-ry*.55)+'Q'+(560-rx*.85)+' 224 '+(560-rx*.45)+' '+(224+ry*.55)+'" fill="none" stroke="#f7fff3" stroke-width="4" opacity=".7"/>'+t(560,228,inflate>0?format(inflate)+' g CO₂':'集氣袋',inflate>0?14:11)+t(560,335,'支架與集氣袋留在秤盤',10)+'</g>';
 if(closed&&added){s+='<rect x="254" y="92" width="50" height="15" rx="3" fill="#a79570" stroke="#8d876b"/><path d="M280 95V66Q280 54 304 54H541Q560 54 560 78V132" fill="none" stroke="#94b6b1" stroke-width="8"/><path d="M280 95V66Q280 54 304 54H541Q560 54 560 78V132" fill="none" stroke="#f5f9eb" stroke-width="3"/>';if(!collect)s+='<rect x="454" y="47" width="21" height="15" fill="#eef4f0"/><path d="M462 52l-4 -12M468 52l7 -12" stroke="#b38459" stroke-width="2"/>'+t(470,30,'接頭未扣緊',11,'#9c754c');}
 else s+='<rect x="380" y="336" width="40" height="12" rx="3" fill="#a79570"/>'+t(398,326,'瓶塞',10);
