 if(progress>0&&!(closed&&collect))s+='<path d="M278 85V47m-5 7 5 -8 5 8" fill="none" stroke="#82a7a5" stroke-width="2"/>'+t(372,55,'跑掉的 CO₂：'+format(r.escaped)+' g',12);
 return s;
