export function materialIcon(kind,formula){
 let shape='';
 if(kind==='cup')shape='<path d="M30 25H64V62Q47 72 30 62Z" fill="#eef3e8" stroke="#9cafa4" stroke-width="2"/><ellipse cx="47" cy="25" rx="17" ry="5" fill="#fffef5" stroke="#9cafa4"/><path d="M32 24L38 17 44 20 50 14 61 25Q47 31 32 24Z" fill="#fffdf1" stroke="#d6d6c7"/><path d="M35 34V59" stroke="#fff" stroke-width="3"/>';
 else if(kind==='ribbon')shape='<path d="M18 63l18 -31 13 8 17 -24" fill="none" stroke="#91a2a6" stroke-width="11"/><path d="M18 60l17 -31 14 8 16 -24" fill="none" stroke="#f3f6f5" stroke-width="3"/>';
 else if(kind==='gas')shape='<path d="M29 23Q46 9 63 23V70Q46 81 29 70Z" fill="#597e7c" stroke="#365f61" stroke-width="2"/><path d="M40 17V7H52V17M36 6H56" fill="none" stroke="#b3aa84" stroke-width="5"/><rect x="35" y="39" width="22" height="22" rx="3" fill="#f1f4e9"/><text x="46" y="54" text-anchor="middle" font-size="12" fill="#526c65">O₂</text>';
 else if(kind==='solution')shape='<path d="M21 15H69L74 10H79L71 20V66Q46 79 21 66Z" fill="#d9e9e8" fill-opacity=".45" stroke="#809f9d" stroke-width="2"/><path d="M24 40Q46 46 68 40V65Q46 75 24 65Z" fill="#afceca" opacity=".7"/><path d="M28 23V62" stroke="#fff" stroke-width="4"/><path d="M54 29h12m-12 10h12m-12 10h12" stroke="#86a8a3"/>';
 else shape='<path d="M11 48Q46 42 81 48L70 68Q46 79 22 68Z" fill="#fffdf2" stroke="#adb5a4" stroke-width="2"/><path d="M20 48L29 37 38 41 48 29 58 39 66 36 74 49Q46 61 20 48Z" fill="'+(kind==='crystal'?'#509ed3':kind==='stone'?'#d1c7a8':'#f9f6e7')+'" stroke="'+(kind==='crystal'?'#3a84b7':'#cccbbd')+'"/>';
 return '<svg class="material-mini" viewBox="0 0 92 86" aria-hidden="true"><ellipse cx="46" cy="76" rx="34" ry="5" fill="#647b6618"/>'+shape+'</svg>';
}
export function stoichBody(formula,mass,products,{revealed=true}={}){
 let s=benchBase('精準煉成 / 從投入量預測產物');
 s+='<rect x="73" y="280" width="201" height="10" rx="5" fill="url(#steel)" stroke="#9bada4"/><path d="M87 290H260L276 348H70Z" fill="#b7c7bb" stroke="#92a99d"/><rect x="101" y="309" width="144" height="27" rx="4" fill="#25453a"/>'+t(173,329,format(mass)+' g',20,'#d5ebcb');
 if(formula==='H2O2')s+='<path d="M140 185H206V263Q173 277 140 263Z" fill="url(#clear-glass)" stroke="#83a3a0" stroke-width="2"/>'+(mass>0?'<path d="M143 '+(263-Math.min(72,mass*1.1))+'H203V261Q173 274 143 261Z" fill="url(#water-fill)"/>':'')+t(173,171,'H₂O₂ 溶質',17);
 else s+=dish(173,235,mass>0?Math.min(mass/10,5):0)+t(173,190,chemicalText(formula),25);
 s+=t(173,380,'投入的純物質／溶質',12)+'<path d="M307 242H376m-11 -9 12 9 -12 9" stroke="#a2b295" stroke-width="3" fill="none"/>'+t(345,220,revealed?'理論結果':'先算，再對照',12);
 const width=products.length===3?103:134;
 products.forEach((original,i)=>{const p=revealed?original:{...original,mass:0,mol:0};const x=435+i*width,gas=['O2','CO2'].includes(p.formula),solid=p.formula==='MgO';
 s+='<g transform="translate('+x+' 0)" data-phase="'+(gas?'gas':solid?'solid':'liquid')+'">';
 if(gas){s+='<path d="M-12 168H12V180H26V294H-26V180H-12Z" fill="url(#clear-glass)" stroke="#83a39b" stroke-width="2"/><path d="M-31 295H31M0 296V318M-17 319H17" stroke="#8c9e91" stroke-width="4"/><path d="M-22 '+(280-Math.min(95,p.mol*60))+'H22" stroke="#9eab98" stroke-width="7"/>'+[220,235,250,265,280].map(y=>'<path d="M14 '+y+'h10" stroke="#839e94"/>').join('')+t(0,142,chemicalText(p.formula),20)+t(0,161,'無色氣體・集氣筒',9);}
 else if(solid)s+=dish(0,260,Math.min(p.mass/10,5))+t(0,205,chemicalText(p.formula),20);
 else s+='<path d="M-35 226H35V300Q0 313 -35 300Z" fill="url(#clear-glass)" stroke="#9bb4ac" stroke-width="2"/>'+(p.mass>0?'<path d="M-32 '+(299-Math.min(68,p.mass*1.3))+'H32V299Q0 310 -32 299Z" fill="url(#water-fill)"/>':'')+t(0,205,chemicalText(p.formula),20);
 s+=t(0,347,revealed?format(p.mass)+' g':'等待計算',revealed?18:13)+t(0,370,revealed?format(p.mol)+' mol':'',11)+'</g>';});
 return s+t(380,419,'填充量與氣筒活塞位置為示意，不代表量測體積',11);
}
